          <p className="hint">
            {meta.source === "google" ? "Live places near you" : "Sample restaurants"}
            {meta.scoring === "jev" ? ", ranked with Jev" : ""}
          </p>
        ) : null}
        {error ? <p className="error" role="alert">{error}</p> : null}
      </>
    )}
  </section>
) : null}

