"use client";

import { createClient } from "@supabase/supabase-js";
import { CSSProperties, FormEvent, PointerEvent, useCallback, useEffect, useMemo, useState } from "react";
import RestaurantPhoto from "./restaurant-photo";

type Location = { latitude: number; longitude: number };
type Vote = "pass" | "interested" | "love";
type DeviceMode = "shared" | "remote";
type Screen = "setup" | "lobby" | "deck" | "waiting" | "result" | "fallback";

type Restaurant = {
  id: string;
  name: string;
  cuisine: string;
  rating: number;
  reviewCount: number;
  priceLevel: number;
  address: string;
  distanceKm: number | null;
  openNow: boolean | null;
  tags: string[];
  orderIdeas: string[];
  mapsUrl: string | null;
  websiteUrl: string | null;
  score: number;
  confidence: number | null;
  why: string;
};

type ResponseMeta = {
  source: "google" | "sample";
  scoring: "jev" | "local";
  notices: string[];
  dietaryNotice: string;
};

type PublicDinnerRoom = {
  code: string;
  createdAt: number;
  expiresAt: number;
  status: "voting" | "complete";
  participants: Array<{
    slot: number;
    name: string;
    joined: boolean;
    completed: boolean;
  }>;
  restaurants: Restaurant[];
  preferences: { cravings: string[]; dietary: string[] };
  meta: ResponseMeta;
  resultRestaurantId: string | null;
  resultSupport: number;
  fallback: boolean;
  revision: number;
};

const CRAVING_OPTIONS = [
  "spicy",
  "noodles",
  "pizza",
  "tacos",
  "comfort food",
  "fresh",
  "crunchy",
  "something new",
];

const DIETARY_OPTIONS = [
  "vegetarian",
  "vegan",
  "gluten-free",
  "dairy-free",
  "nut allergy",
  "halal",
];

const VIBES = [
  { value: "cozy and comforting", label: "Cozy", symbol: "☁" },
