  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 26px 24px 22px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.card.behind {
  transform: scale(0.94) translateY(26px);
  opacity: 0.6;
  box-shadow: none;
}

.card.front {
  position: relative;
  inset: auto;
  min-width: 0;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
  transition: transform 0.25s ease;
}

.card.front.dragging {
  cursor: grabbing;
  transition: none;
}

.restaurant-photo {
  margin: 0 0 18px;
}

.restaurant-photo img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border-radius: 12px;
}

.restaurant-photo figcaption {
  margin-top: 6px;
  color: var(--ink-2);
  font-size: 0.72rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.restaurant-photo a {
  text-underline-offset: 2px;
}

.card-kicker {
  display: flex;
  justify-content: space-between;
  color: var(--ink-2);
  font-size: 0.92rem;
}

.card h2 {
  margin: 20px 0 12px;
  font-size: clamp(2.05rem, 9.5vw, 2.6rem);
  line-height: 1.04;
}

